// Strategy interface: how a post is scored for feed ranking.
interface PostScoringStrategy {
    double score(Post post, int currentTime);
}

// Combines engagement (likes plus double-weighted comments) with a time-decay factor.
class EngagementDecayScoringStrategy implements PostScoringStrategy {
    @Override
    public double score(Post post, int currentTime) {
        double engagement = post.getLikeCount() + 2.0 * post.getCommentCount(); // comments count double
        int hoursAgo = Math.max(0, currentTime-post.getTimestamp());              // elapsed time, never negative
        return engagement / (1.0 + hoursAgo); // decays as the post ages, but never divides by zero
    }
}

// Observer interface: reacts to social lifecycle events.
interface SocialObserver {
    void onUserFollowed(String followerId, String followeeId);                    // follow succeeded
    void onFollowRejected(String followerId, String followeeId, String reason);     // follow blocked or duplicate
    void onUserUnfollowed(String followerId, String followeeId);                     // follow removed voluntarily
    void onUserBlocked(String blockerId, String blockedId);                           // block applied
}

// Simple observer that prints events to the console.
class ConsoleSocialObserver implements SocialObserver {
    @Override
    public void onUserFollowed(String followerId, String followeeId) {
        System.out.println(followerId + " followed " + followeeId);
    }

    @Override
    public void onFollowRejected(String followerId, String followeeId, String reason) {
        System.out.println("Follow rejected: " + followerId + " to " + followeeId + ": " + reason);
    }

    @Override
    public void onUserUnfollowed(String followerId, String followeeId) {
        System.out.println(followerId + " unfollowed " + followeeId);
    }

    @Override
    public void onUserBlocked(String blockerId, String blockedId) {
        System.out.println(blockerId + " blocked " + blockedId);
    }
}

