#include <string>
#include <iostream>
using namespace std;

// Strategy interface: how a post is scored for feed ranking.
class PostScoringStrategy {
public:
    virtual double score(const Post& post, int currentTime) = 0;
    virtual ~PostScoringStrategy() {}
};

// Combines engagement (likes plus double-weighted comments) with a time-decay factor.
class EngagementDecayScoringStrategy : public PostScoringStrategy {
public:
    double score(const Post& post, int currentTime) override {
        double engagement = post.likeCount + 2.0 * post.commentCount; // comments count double
        int hoursAgo = max(0, currentTime-post.timestamp);              // elapsed time, never negative
        return engagement / (1.0 + hoursAgo); // decays as the post ages, but never divides by zero
    }
};

// Observer interface: reacts to social lifecycle events.
class SocialObserver {
public:
    virtual void onUserFollowed(const string& followerId, const string& followeeId) = 0;
    virtual void onFollowRejected(const string& followerId, const string& followeeId, const string& reason) = 0;
    virtual void onUserUnfollowed(const string& followerId, const string& followeeId) = 0;
    virtual void onUserBlocked(const string& blockerId, const string& blockedId) = 0;
    virtual ~SocialObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleSocialObserver : public SocialObserver {
public:
    void onUserFollowed(const string& followerId, const string& followeeId) override {
        cout << followerId << " followed " << followeeId << endl;
    }
    void onFollowRejected(const string& followerId, const string& followeeId, const string& reason) override {
        cout << "Follow rejected: " << followerId << " to " << followeeId << ": " << reason << endl;
    }
    void onUserUnfollowed(const string& followerId, const string& followeeId) override {
        cout << followerId << " unfollowed " << followeeId << endl;
    }
    void onUserBlocked(const string& blockerId, const string& blockedId) override {
        cout << blockerId << " blocked " << blockedId << endl;
    }
};

