// Custom exceptions for the realistic failure modes.
class FollowNotAllowedException extends RuntimeException {
    public FollowNotAllowedException(String msg) { super(msg); }
}
class AlreadyFollowingException extends RuntimeException {
    public AlreadyFollowingException(String msg) { super(msg); }
}
class InvalidUserException extends RuntimeException {
    public InvalidUserException(String msg) { super(msg); }
}

// The core orchestrator tying every piece together.
class SocialNetworkService {
    private final java.util.Map<String, User> users = new java.util.HashMap<>();          // userId -> User
    private final java.util.Map<String, java.util.List<Post>> posts = new java.util.HashMap<>(); // authorId -> their posts
    private final PostScoringStrategy scoringStrategy; // pluggable ranking policy
    private final java.util.List<SocialObserver> observers = new java.util.ArrayList<>(); // listeners

    public SocialNetworkService(PostScoringStrategy scoringStrategy) {
        this.scoringStrategy = scoringStrategy; // store chosen policy
    }

    public void addUser(User user) { users.put(user.getUserId(), user); posts.put(user.getUserId(), new java.util.ArrayList<>()); } // register a user
    public void addObserver(SocialObserver observer) { observers.add(observer); } // register a listener
    public void addPost(Post post) { posts.get(post.getAuthorId()).add(post); }     // record a post

    // Follows a user, rejecting if blocked or already following.
    public synchronized void follow(String followerId, String followeeId) {
        User followee = users.get(followeeId);                                       // look up target
        if (followee.getBlockedUsers().contains(followerId)) {                          // target has blocked the requester
            for (SocialObserver obs : observers) obs.onFollowRejected(followerId, followeeId, "Blocked by target user"); // notify
            throw new FollowNotAllowedException(followeeId + " has blocked " + followerId);
        }
        User follower = users.get(followerId);                                          // look up requester
        if (follower.getFollowing().contains(followeeId)) {                               // already following
            for (SocialObserver obs : observers) obs.onFollowRejected(followerId, followeeId, "Already following"); // notify
            throw new AlreadyFollowingException(followerId + " already follows " + followeeId);
        }
        follower.getFollowing().add(followeeId);                                           // add the directed edge
        for (SocialObserver obs : observers) obs.onUserFollowed(followerId, followeeId);    // notify
    }

    // Removes an existing follow relationship.
    public synchronized void unfollow(String followerId, String followeeId) {
        users.get(followerId).getFollowing().remove(followeeId);            // drop the edge if present
        for (SocialObserver obs : observers) obs.onUserUnfollowed(followerId, followeeId); // notify
    }

    // Blocks a user, severing any existing follow edge between the pair in either direction.
    public synchronized void blockUser(String blockerId, String blockedId) {
        users.get(blockerId).getBlockedUsers().add(blockedId);                 // record the block
        users.get(blockedId).getFollowing().remove(blockerId);                   // blocked user no longer follows the blocker
        users.get(blockerId).getFollowing().remove(blockedId);                    // blocker no longer follows the blocked user either
        for (SocialObserver obs : observers) obs.onUserBlocked(blockerId, blockedId); // notify
    }

    // Gathers posts from everyone followed, scores them, and returns them sorted descending.
    public java.util.List<Post> generateFeed(String userId, int currentTime) {
        java.util.List<Post> candidates = new java.util.ArrayList<>();          // gathered posts
        for (String followedId : users.get(userId).getFollowing()) {             // scan every followed account
            candidates.addAll(posts.get(followedId));                              // include all their posts
        }
        candidates.sort((a, b) -> Double.compare(                                  // sort descending by score
                scoringStrategy.score(b, currentTime), scoringStrategy.score(a, currentTime)));
        return candidates; // ranked feed
    }
}

