#include <string>
#include <vector>
#include <map>
#include <set>
#include <memory>
#include <algorithm>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class FollowNotAllowedException : public runtime_error {
public: FollowNotAllowedException(const string& msg) : runtime_error(msg) {}
};
class AlreadyFollowingException : public runtime_error {
public: AlreadyFollowingException(const string& msg) : runtime_error(msg) {}
};
class InvalidUserException : public runtime_error {
public: InvalidUserException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class SocialNetworkService {
    map<string, User> users;                        // userId -> User
    map<string, vector<Post>> posts;                // authorId -> their posts
    shared_ptr<PostScoringStrategy> scoringStrategy; // pluggable ranking policy
    vector<shared_ptr<SocialObserver>> observers;     // listeners

public:
    SocialNetworkService(shared_ptr<PostScoringStrategy> strategy) : scoringStrategy(strategy) {}

    void addUser(User user) { users.insert({user.userId, user}); posts[user.userId] = {}; } // register a user
    void addObserver(shared_ptr<SocialObserver> observer) { observers.push_back(observer); } // register a listener
    void addPost(Post post) { posts[post.authorId].push_back(post); } // record a post

    void follow(string followerId, string followeeId) {
        User& followee = users.at(followeeId);                                 // look up target
        if (followee.blockedUsers.count(followerId)) {                            // target has blocked the requester
            for (auto& obs : observers) obs->onFollowRejected(followerId, followeeId, "Blocked by target user"); // notify
            throw FollowNotAllowedException(followeeId + " has blocked " + followerId);
        }
        User& follower = users.at(followerId);                                    // look up requester
        if (follower.following.count(followeeId)) {                                 // already following
            for (auto& obs : observers) obs->onFollowRejected(followerId, followeeId, "Already following"); // notify
            throw AlreadyFollowingException(followerId + " already follows " + followeeId);
        }
        follower.following.insert(followeeId);                                       // add the directed edge
        for (auto& obs : observers) obs->onUserFollowed(followerId, followeeId);       // notify
    }

    void unfollow(string followerId, string followeeId) {
        users.at(followerId).following.erase(followeeId);                     // drop the edge if present
        for (auto& obs : observers) obs->onUserUnfollowed(followerId, followeeId); // notify
    }

    void blockUser(string blockerId, string blockedId) {
        users.at(blockerId).blockedUsers.insert(blockedId);                    // record the block
        users.at(blockedId).following.erase(blockerId);                         // blocked user no longer follows the blocker
        users.at(blockerId).following.erase(blockedId);                          // blocker no longer follows the blocked user either
        for (auto& obs : observers) obs->onUserBlocked(blockerId, blockedId);      // notify
    }

    vector<Post> generateFeed(string userId, int currentTime) {
        vector<Post> candidates;                                              // gathered posts
        for (auto& followedId : users.at(userId).following) {                    // scan every followed account
            for (auto& post : posts[followedId]) candidates.push_back(post);        // include all their posts
        }
        std::sort(candidates.begin(), candidates.end(), [&](const Post& a, const Post& b) { // sort descending by score
            return scoringStrategy->score(a, currentTime) > scoringStrategy->score(b, currentTime);
        });
        return candidates; // ranked feed
    }
};

