#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <memory>
#include <algorithm>
#include <stdexcept>
using namespace std;

class User {
public:
    string userId;
    string name;
    set<string> following;
    set<string> blockedUsers;

    User() {}
    User(string id, string n) : userId(id), name(n) {}
};

class Post {
public:
    string postId;
    string authorId;
    string content;
    int timestamp;
    int likeCount;
    int commentCount;

    Post() {}
    Post(string id, string author, string c, int ts, int likes, int comments)
        : postId(id), authorId(author), content(c), timestamp(ts), likeCount(likes), commentCount(comments) {}
};

class PostFactory {
    int counter = 0;

public:
    Post createPost(string authorId, string content, int timestamp, int likeCount, int commentCount) {
        counter++;
        return Post("POST-" + to_string(counter), authorId, content, timestamp, likeCount, commentCount);
    }
};

class PostScoringStrategy {
public:
    virtual double score(const Post& post, int currentTime) = 0;
    virtual ~PostScoringStrategy() {}
};

class EngagementDecayScoringStrategy : public PostScoringStrategy {
public:
    double score(const Post& post, int currentTime) override {
        double engagement = post.likeCount + 2.0 * post.commentCount;
        int hoursAgo = max(0, currentTime-post.timestamp);
        return engagement / (1.0 + hoursAgo);
    }
};

class SocialObserver {
public:
    virtual void onUserFollowed(const string& followerId, const string& followeeId) = 0;
    virtual void onFollowRejected(const string& followerId, const string& followeeId, const string& reason) = 0;
    virtual void onUserUnfollowed(const string& followerId, const string& followeeId) = 0;
    virtual void onUserBlocked(const string& blockerId, const string& blockedId) = 0;
    virtual ~SocialObserver() {}
};

class ConsoleSocialObserver : public SocialObserver {
public:
    void onUserFollowed(const string& followerId, const string& followeeId) override {
        cout << followerId << " followed " << followeeId << endl;
    }
    void onFollowRejected(const string& followerId, const string& followeeId, const string& reason) override {
        cout << "Follow rejected: " << followerId << " to " << followeeId << ": " << reason << endl;
    }
    void onUserUnfollowed(const string& followerId, const string& followeeId) override {
        cout << followerId << " unfollowed " << followeeId << endl;
    }
    void onUserBlocked(const string& blockerId, const string& blockedId) override {
        cout << blockerId << " blocked " << blockedId << endl;
    }
};

class FollowNotAllowedException : public runtime_error {
public: FollowNotAllowedException(const string& msg) : runtime_error(msg) {}
};
class AlreadyFollowingException : public runtime_error {
public: AlreadyFollowingException(const string& msg) : runtime_error(msg) {}
};
class InvalidUserException : public runtime_error {
public: InvalidUserException(const string& msg) : runtime_error(msg) {}
};

class SocialNetworkService {
    map<string, User> users;
    map<string, vector<Post>> posts;
    shared_ptr<PostScoringStrategy> scoringStrategy;
    vector<shared_ptr<SocialObserver>> observers;

public:
    SocialNetworkService(shared_ptr<PostScoringStrategy> strategy) : scoringStrategy(strategy) {}

    void addUser(User user) { users.insert({user.userId, user}); posts[user.userId] = {}; }
    void addObserver(shared_ptr<SocialObserver> observer) { observers.push_back(observer); }
    void addPost(Post post) { posts[post.authorId].push_back(post); }

    void follow(string followerId, string followeeId) {
        User& followee = users.at(followeeId);
        if (followee.blockedUsers.count(followerId)) {
            for (auto& obs : observers) obs->onFollowRejected(followerId, followeeId, "Blocked by target user");
            throw FollowNotAllowedException(followeeId + " has blocked " + followerId);
        }
        User& follower = users.at(followerId);
        if (follower.following.count(followeeId)) {
            for (auto& obs : observers) obs->onFollowRejected(followerId, followeeId, "Already following");
            throw AlreadyFollowingException(followerId + " already follows " + followeeId);
        }
        follower.following.insert(followeeId);
        for (auto& obs : observers) obs->onUserFollowed(followerId, followeeId);
    }

    void unfollow(string followerId, string followeeId) {
        users.at(followerId).following.erase(followeeId);
        for (auto& obs : observers) obs->onUserUnfollowed(followerId, followeeId);
    }

    void blockUser(string blockerId, string blockedId) {
        users.at(blockerId).blockedUsers.insert(blockedId);
        users.at(blockedId).following.erase(blockerId);
        users.at(blockerId).following.erase(blockedId);
        for (auto& obs : observers) obs->onUserBlocked(blockerId, blockedId);
    }

    vector<Post> generateFeed(string userId, int currentTime) {
        vector<Post> candidates;
        for (auto& followedId : users.at(userId).following) {
            for (auto& post : posts[followedId]) candidates.push_back(post);
        }
        std::sort(candidates.begin(), candidates.end(), [&](const Post& a, const Post& b) {
            return scoringStrategy->score(a, currentTime) > scoringStrategy->score(b, currentTime);
        });
        return candidates;
    }
};

int main() {
    auto service = SocialNetworkService(make_shared<EngagementDecayScoringStrategy>());
    service.addObserver(make_shared<ConsoleSocialObserver>());
    PostFactory factory;

    service.addUser(User("Alice", "Alice"));
    service.addUser(User("Bob", "Bob"));
    service.addUser(User("Carol", "Carol"));

    service.follow("Alice", "Bob");
    service.follow("Alice", "Carol");

    service.blockUser("Carol", "Alice");

    try {
        service.follow("Alice", "Carol");
    } catch (FollowNotAllowedException& e) {
        cout << "Caught expected: " << e.what() << endl;
    }

    service.addPost(factory.createPost("Bob", "Post1", 0, 10, 2));
    service.addPost(factory.createPost("Bob", "Post2", 5, 1, 0));

    vector<Post> feed = service.generateFeed("Alice", 10);
    for (auto& post : feed) {
        cout << "Feed item: " << post.content << endl;
    }

    return 0;
}
